def resolve(path, cwd, links):
    if not cwd.startswith('/'):
        return None

    # Normalize cwd to not have trailing slash (except for root)
    if cwd != '/' and cwd.endswith('/'):
        cwd = cwd.rstrip('/')

    # Start with cwd if path is relative, otherwise start with root
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                # Move to parent
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component
        if current == '/':
            new_path = '/' + comp
        else:
            new_path = current + '/' + comp

        # Check if it's a symlink
        if new_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[new_path]

            # Parse remaining components
            remaining = components[i+1:]

            # Parse target components
            if target.startswith('/'):
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Target is relative to the directory containing the link
                if current == '/':
                    current = '/'
                    target_components = target.split('/')
                else:
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                    target_components = target.split('/')

            # Replace components with target components + remaining
            components = target_components + remaining
            i = 0
        else:
            current = new_path
            i += 1

    # Return result without trailing slash (except for root)
    if current == '':
        return '/'
    return current

